// ── Funzioni comuni del 15 (copiate in testa a ogni nodo Code dal costruttore) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const due = (n) => String(n).padStart(2, '0');
const has = (o, k) => Object.prototype.hasOwnProperty.call(o || {}, k);
const corto = (s, n) => { const c = Array.from(String(s ?? '')); return c.length > n ? c.slice(0, n - 1).join('') + '…' : String(s ?? ''); };
// HTML per sendMessage con parse_mode HTML
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram con i pulsanti (sendAndWait) usa sempre il Markdown semplice (fissato nel codice di n8n): si neutralizzano _ * ` [
const md = (v) => String(v ?? '').replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const siNo = (v, seVuoto) => { const t = testo(v).toLowerCase(); if (!t) return seVuoto; return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t); };
// Il consenso alle anteprime con persone vale SOLO se nella cella c'è esattamente «si» (o «sì»): niente x, ok, 1, true.
const consensoFirmato = (v) => ['si', 'sì'].includes(testo(v).toLowerCase());
const lette = (nodo) => $(nodo).all().map((i) => i.json || {}).filter((r) => has(r, 'row_number')); // solo righe vere del foglio
const partiRoma = (ms) => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
const romaMs = (a, me, g, o, mi) => {
  const base = Date.UTC(a, me - 1, g, o, mi);
  for (const off of [60, 120]) { const t = base - off * 60000; const p = partiRoma(t); if (p.anno === a && p.mese === me && p.giorno === g && p.ore === o && p.minuti === mi) return t; }
  return null;
};
const oraRoma = (ms) => { const p = partiRoma(ms); return `${p.anno}-${due(p.mese)}-${due(p.giorno)} ${due(p.ore)}:${due(p.minuti)}`; };
const timbro = (ms) => { const p = partiRoma(ms); return `${due(p.giorno)}/${due(p.mese)} ${due(p.ore)}:${due(p.minuti)}`; };
const giorniNelMese = (a, me) => new Date(Date.UTC(a, me, 0)).getUTCDate();
const GIORNI_BREVI = ['dom', 'lun', 'mar', 'mer', 'gio', 'ven', 'sab'];
// data_ora come la leggono 04 e 10: testo AAAA-MM-GG HH:MM, GG/MM/AAAA HH:MM, oppure numero di Sheets
const leggiDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 1440) * 60000);
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
    if (m) [a, me, g, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    else {
      m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}),? (\d{1,2})[:.](\d{2})/);
      if (!m) return null;
      [g, me, a, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    }
  }
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me) && o >= 0 && o <= 23 && mi >= 0 && mi <= 59)) return null;
  const ms = romaMs(a, me, g, o, mi);
  return { chiave: `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`, ms,
    leggibile: `${GIORNI_BREVI[new Date(Date.UTC(a, me - 1, g)).getUTCDay()]} ${g}/${me} ore ${due(o)}:${due(mi)}` };
};
// link di Drive come li legge il 01: /file/d/<id>/view, ?id=<id> oppure l'id nudo. Le cartelle no.
const idDaLink = (voce) => {
  const t = testo(voce);
  if (!t || /\/folders\//.test(t)) return '';
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
};
const vociMedia = (r) => testo(r.media).split('|').map((s) => s.trim()).filter(Boolean);
const impronta = (s) => { let h = 5381; for (const ch of String(s ?? '')) h = ((h * 33) ^ ch.codePointAt(0)) >>> 0; return h.toString(16); };
// note che appartengono al motore (06/07/08): il 15 non tocca mai quelle righe e non scrive mai questi pezzi
const NOTE_DEL_MOTORE = ['[06]', '[07 cartella ', '[08:'];
const notaDelMotore = (n) => NOTE_DEL_MOTORE.some((x) => String(n ?? '').includes(x));
const msDi = (v) => { const d = leggiDataOra(v); return d && d.ms !== null ? d.ms : null; };
// impronta di quello che decide COME e DOVE esce la storia: se cambia dopo la domanda, l'approvazione non vale più
const improntaRiga = (r) => impronta(['cliente', 'piattaforme', 'tag_persone', 'collaboratori', 'copertina'].map((c) => testo(r[c])).join('␟'));

// Sceglie le storie da mandare in approvazione su Telegram. Non scrive niente nel foglio: esce con un item solo.
// Prende: tipo «storia», stato «da_approvare», un solo file di Drive in «media», note SENZA «[06]» (quelle le chiede il 06),
// cliente attivo nella scheda Clienti, data_ora tra MINUTI_MINIMI minuti e GIORNI_AVANTI giorni.
//
// Traccia (scheda a parte, scritta solo in fondo). Ogni domanda ha un token (il giro che l'ha fatta). Una domanda è
// APERTA se il suo token ha una riga «prenotato» o «chiesto» con scade_il nel futuro e nessuna riga di chiusura con lo
// stesso token. «prenotato» (scritto dal giro) dura pochi minuti; «chiesto» (scritto dal sotto-flusso subito prima di
// mandare la domanda) dura fino alla fine dell'attesa più un margine. Se il sotto-flusso non parte mai, la prenotazione
// scade da sola e la storia si richiede: nessuna domanda si perde in silenzio.
// In prova la traccia è nella memoria del flusso (niente scritture nel foglio).
const cfg = $('Config').first().json;
const vero = testo(cfg.MODALITA).toLowerCase() === 'vero';
const adesso = Date.now();
const MIN = 60000;
const ORA = 3600000;
const minutiMinimi = Number(cfg.MINUTI_MINIMI) || 15;
const margine = Number(cfg.MINUTI_MARGINE) || 3;
const giorniAvanti = Number(cfg.GIORNI_AVANTI) || 7;
const oreMaxAttesa = Number(cfg.ORE_MAX_ATTESA) || 4;
const oreVicine = Number(cfg.ORE_VICINE) || 6;
const oreAllarme = Number(cfg.ORE_ALLARME) || 2;
const orePausaScaduta = Number(cfg.ORE_PAUSA_DOPO_SCADUTA) || 12;
const maxPerGiro = Math.max(0, Number(cfg.MAX_PER_GIRO) || 5);
const maxVicine = Math.max(1, Number(cfg.MAX_VICINE_PER_GIRO) || 10);
const maxInAttesa = Math.max(0, Number(cfg.MAX_IN_ATTESA) || 10);
const schedaTraccia = testo(cfg.SCHEDA_TRACCIA) || 'Approvazioni storie';
// Notte: dalle ORA_INIZIO_NOTTE alle ORA_FINE_NOTTE niente domande né avvisi normali, salvo le storie che escono prima
// delle ORA_ECCEZIONE_NOTTE (la mattina presto) e gli allarmi urgenti («approvala dal foglio»).
const oraAdesso = partiRoma(adesso);
const inizioNotte = Number(cfg.ORA_INIZIO_NOTTE ?? 23);
const fineNotte = Number(cfg.ORA_FINE_NOTTE ?? 7);
const oraEccezione = Number(cfg.ORA_ECCEZIONE_NOTTE ?? 9);
const notte = inizioNotte > fineNotte ? (oraAdesso.ore >= inizioNotte || oraAdesso.ore < fineNotte) : (oraAdesso.ore >= inizioNotte && oraAdesso.ore < fineNotte);
let limiteNotte = romaMs(oraAdesso.anno, oraAdesso.mese, oraAdesso.giorno, oraEccezione, 0);
if (limiteNotte === null || limiteNotte <= adesso) { const dom = partiRoma(adesso + 86400000); limiteNotte = romaMs(dom.anno, dom.mese, dom.giorno, oraEccezione, 0); }
const minutiErroreVicina = Number(cfg.MINUTI_RIPROVA_VICINE) || 15;
const CHIUSURE = ['approvato', 'rifiutato', 'non applicato', 'scaduto', 'errore telegram'];

// --- traccia ---
const grezza = $('Leggi la traccia').all().map((i) => i.json || {});
if (vero && grezza.some((r) => r && r.error)) {
  throw new Error(`15 fermo: la scheda «${schedaTraccia}» non si legge. Senza la traccia chiederei le stesse storie ogni 15 minuti: creala con le intestazioni del PROGETTO.`);
}
const traccia = grezza.filter((r) => has(r, 'row_number') && testo(r.chiave)).sort((a, b) => Number(a.row_number) - Number(b.row_number));
const perChiave = {};
for (const t of traccia) (perChiave[testo(t.chiave)] = perChiave[testo(t.chiave)] || []).push(t);
// stato di ogni token su una chiave: { prima: riga della prima prenotazione, scade: massimo scade_il, chiuso, esitoChiusura, quando, dettaglio }
const tokenDi = (k) => {
  const m = new Map();
  for (const t of perChiave[k] || []) {
    const tok = testo(t.token) || `riga ${t.row_number}`;
    const e = testo(t.esito).toLowerCase();
    const x = m.get(tok) || { prima: Number(t.row_number), scade: -Infinity, chiuso: false };
    if (e === 'prenotato' || e === 'chiesto') { const s = msDi(t.scade_il); x.scade = Math.max(x.scade, s === null ? Infinity : s); } // scadenza illeggibile: prudenza
    if (CHIUSURE.includes(e)) { x.chiuso = true; x.esitoChiusura = e; x.quando = msDi(t.data_ora); x.dettaglio = testo(t.dettaglio); x.riga = Number(t.row_number); }
    m.set(tok, x);
  }
  return m;
};
const aperta = (x) => !x.chiuso && x.scade > adesso;
const ultimaChiusura = (k) => [...tokenDi(k).values()].filter((x) => x.chiuso).sort((a, b) => b.riga - a.riga)[0] || null;

const memoria = $getWorkflowStaticData('global');
memoria.chiesti = memoria.chiesti || {};
memoria.avvisati = memoria.avvisati || {};
memoria.vicine = memoria.vicine || {};
memoria.tentate = memoria.tentate || {};
for (const g of ['chiesti', 'avvisati', 'tentate']) for (const k of Object.keys(memoria[g])) if (memoria[g][k] < adesso) { delete memoria[g][k]; delete memoria.vicine[k]; }

// motivo per cui una chiave NON si chiede adesso (stringa vuota = si può chiedere)
const bloccata = (k, vicina) => {
  if (!vero) return (memoria.chiesti[k] || 0) > adesso ? 'aperta' : '';
  if ([...tokenDi(k).values()].some(aperta)) return 'aperta';
  const u = ultimaChiusura(k);
  // dopo un errore di Telegram: un'ora per le storie lontane, 15 minuti per quelle vicine all'uscita
  if (u && u.esitoChiusura === 'errore telegram' && (u.quando === null || adesso - u.quando < (vicina ? minutiErroreVicina * MIN : ORA))) return 'errore recente';
  if (u && u.esitoChiusura === 'scaduto' && !vicina && u.quando !== null && adesso - u.quando < orePausaScaduta * ORA) return 'pausa dopo scaduta';
  return '';
};
const giaAvvisato = (k) => {
  if (!vero) return (memoria.avvisati[k] || 0) > adesso;
  const ultima = (perChiave[k] || []).at(-1);
  return !!ultima && testo(ultima.esito).toLowerCase() === 'avvisato' && (msDi(ultima.data_ora) ?? 0) > adesso - 24 * ORA;
};

// --- clienti e archivio ---
const clienti = {};
for (const c of lette('Leggi i clienti')) { const k = testo(c.cliente); if (k && !has(clienti, k)) clienti[k] = c; } // il 01 prende la prima riga
const descrizioni = {};
for (const a of $('Leggi archivio file').all().map((i) => i.json || {})) {
  if (has(a, 'row_number') && testo(a.file_id) && testo(a.descrizione) && testo(a.descrizione) !== 'senza miniatura') descrizioni[testo(a.file_id)] = testo(a.descrizione);
}

// --- calendario ---
const righe = lette('Leggi il calendario');
const quanteVolte = {};
for (const r of righe) { const k = testo(r.id); if (k) quanteVolte[k] = (quanteVolte[k] || 0) + 1; }

const candidate = [];
const avvisi = [];
const avvisa = (r, problema, sotto = '', urgente = false) => {
  if (notte && !urgente) return; // gli avvisi normali aspettano la mattina
  const chiave = `avviso|${testo(r.id) || 'riga ' + r.row_number}|${impronta(problema.replace(/\d+ minuti/, ''))}${sotto}`;
  if (!giaAvvisato(chiave)) avvisi.push({ chiave, id: testo(r.id), row_number: r.row_number, cliente: testo(r.cliente), problema, urgente });
};
for (const r of righe) {
  if (testo(r.tipo).toLowerCase() !== 'storia') continue;
  if (testo(r.stato).toLowerCase() !== 'da_approvare') continue;
  if (!vociMedia(r).length) continue; // senza file: non c'è niente da far vedere (le chiede il foglio o il 06)
  if (notaDelMotore(r.note)) continue; // storie del 06: le manda in approvazione il 06
  const d = leggiDataOra(r.data_ora);
  const ms = d && d.ms !== null ? d.ms : null;
  if (ms === null || ms <= adesso || ms > adesso + giorniAvanti * 86400000) continue;
  if (ms < adesso + minutiMinimi * MIN) {
    // troppo tardi per chiedere: se la domanda non è mai arrivata (mai chiesta, o l'ultimo tentativo è un errore di Telegram)
    // lo si dice, invece di tacere. Se una domanda è ancora aperta, risponde quella.
    const idT = testo(r.id); const fT = idDaLink(vociMedia(r)[0] || '');
    const kT = idT && fT ? `${idT}|${fT}|${d.chiave}` : '';
    let silenzio;
    if (!kT) silenzio = false; // id o file sbagliati: c'è già l'avviso dedicato quando c'era tempo
    else if (!vero) silenzio = !memoria.chiesti[kT] && !memoria.tentate?.[kT];
    else {
      const aperteT = [...tokenDi(kT).values()].some(aperta);
      const u = ultimaChiusura(kT);
      silenzio = !aperteT && (!u || u.esitoChiusura === 'errore telegram');
    }
    if (silenzio && clienti[testo(r.cliente)] && siNo(clienti[testo(r.cliente)].attivo, false)) {
      avvisa(r, `la storia ${corto(idT, 40)} esce ${d.leggibile} e non riesco più a chiedertela in tempo: approvala dal foglio se deve uscire`, '|tardi', true);
    }
    continue;
  }
  if (notte && ms >= limiteNotte) continue; // di notte solo le storie che escono prima delle 9
  const cliente = clienti[testo(r.cliente)];
  if (!cliente) { avvisa(r, `il cliente «${corto(testo(r.cliente) || 'vuoto', 40)}» non c'è nella scheda Clienti: non la mando in approvazione`); continue; }
  if (!siNo(cliente.attivo, false)) continue; // cliente spento: il 01 non pubblicherebbe comunque
  const id = testo(r.id);
  if (!id) { avvisa(r, `la storia alla riga ${r.row_number} non ha l'id: non la posso approvare da Telegram`); continue; }
  if (String(r.id) !== id) { avvisa(r, `l'id «${corto(id, 40)}» ha spazi prima o dopo: toglili, poi arriva l'approvazione`); continue; }
  if (quanteVolte[id] > 1) { avvisa(r, `l'id «${corto(id, 40)}» è in ${quanteVolte[id]} righe: dagli un id unico, poi arriva l'approvazione`); continue; }
  const voci = vociMedia(r);
  if (voci.length !== 1) { avvisa(r, `la storia ${corto(id, 40)} ha ${voci.length} file in media: una storia ne vuole uno solo (il 01 la fermerebbe)`); continue; }
  const fileId = idDaLink(voci[0]);
  if (!fileId) { avvisa(r, `il file della storia ${corto(id, 40)} non è un link di un file di Google Drive`); continue; }
  const chiave = `${id}|${fileId}|${d.chiave}`;
  const vicina = ms - adesso <= oreVicine * ORA;
  if (bloccata(chiave, vicina)) continue;
  const u = vero ? ultimaChiusura(chiave) : null;
  candidate.push({ r, id, d, ms, fileId, chiave, cliente, vicina,
    riprova: !!(u && u.esitoChiusura === 'errore telegram' && /anteprima mandata/.test(u.dettaglio || '')) });
}

// domande aperte che contano nel tetto: solo quelle delle storie lontane (le vicine passano sempre)
let aperte = 0;
if (vero) {
  for (const k of Object.keys(perChiave)) {
    if (k.startsWith('avviso|')) continue;
    if (![...tokenDi(k).values()].some(aperta)) continue;
    const esce = msDi(k.split('|')[2]);
    if (esce === null || esce - adesso > oreVicine * ORA) aperte++;
  }
} else aperte = Object.keys(memoria.chiesti).filter((k) => !memoria.vicine[k]).length;

candidate.sort((a, b) => a.ms - b.ms || a.r.row_number - b.r.row_number);
const vicine = candidate.filter((x) => x.vicina);
const lontane = candidate.filter((x) => !x.vicina);
const scelteVicine = vicine.slice(0, maxVicine);
const posti = Math.max(0, Math.min(maxPerGiro, maxInAttesa - aperte));
const scelte = [...scelteVicine, ...lontane.slice(0, posti)];
// una storia che esce a breve e resta fuori lo stesso: lo si dice subito
for (const x of vicine.slice(maxVicine)) {
  if (x.ms - adesso <= oreAllarme * ORA) avvisa(x.r, `la storia ${corto(x.id, 40)} esce ${x.d.leggibile} ma ci sono troppe storie da approvare insieme: approvala dal foglio`, '|fuori', true);
}

const token = `${$execution.id}-${adesso}`;
const suMinuto = (ms) => Math.ceil(ms / MIN) * MIN;
const storie = scelte.map((x) => {
  const fineUscita = x.ms - margine * MIN;
  const fine = Math.min(fineUscita, adesso + oreMaxAttesa * ORA);
  if (!vero) { memoria.chiesti[x.chiave] = suMinuto(fine + 2 * MIN); if (x.vicina) memoria.vicine[x.chiave] = true; memoria.tentate = memoria.tentate || {}; memoria.tentate[x.chiave] = x.ms + ORA; }
  return {
    chiave: x.chiave, id: x.id, row_number: x.r.row_number, cliente: testo(x.r.cliente),
    nome_locale: testo(x.cliente.nome_locale) || testo(x.r.cliente),
    consenso: consensoFirmato(x.cliente.anteprime_con_persone),
    data_ora: x.d.chiave, esce_leggibile: x.d.leggibile, esce_ms: x.ms,
    file_id: x.fileId, media: testo(x.r.media), note: testo(x.r.note), piattaforme: testo(x.r.piattaforme),
    impronta_riga: improntaRiga(x.r),
    brief: corto(testo(x.r.brief), 700), descrizione_archivio: corto(descrizioni[x.fileId] || '', 400),
    // la domanda si chiude a quest'ora esatta (atSpecifiedTime), qualunque ritardo abbia avuto il sotto-flusso
    fine_iso: new Date(fine).toISOString(), fine_leggibile: oraRoma(fine),
    attesa_minuti: Math.max(1, Math.floor((fine - adesso) / MIN)), // solo informativo: la fine vera è fine_iso
    // nella traccia: fine attesa più 2 minuti, arrotondata al minuto SUCCESSIVO (mai prima della fine vera)
    scade_il: oraRoma(suMinuto(fine + 2 * MIN)),
    ultima_occasione: fine === fineUscita, vicina: x.vicina, riprova_senza_anteprima: x.riprova,
  };
});
// gli avvisi si segnano come «avvisati» solo DOPO un invio riuscito (nodo «Righe avvisate»): un invio fallito si ripete al giro dopo

return [{ json: { token, modalita: vero ? 'vero' : 'prova', notte, storie, avvisi, aperte, posti, rimaste: candidate.length - scelte.length } }];

// ── Funzioni comuni del 15 (copiate in testa a ogni nodo Code dal costruttore) ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const due = (n) => String(n).padStart(2, '0');
const has = (o, k) => Object.prototype.hasOwnProperty.call(o || {}, k);
const corto = (s, n) => { const c = Array.from(String(s ?? '')); return c.length > n ? c.slice(0, n - 1).join('') + '…' : String(s ?? ''); };
// HTML per sendMessage con parse_mode HTML
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram con i pulsanti (sendAndWait) usa sempre il Markdown semplice (fissato nel codice di n8n): si neutralizzano _ * ` [
const md = (v) => String(v ?? '').replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1');
const siNo = (v, seVuoto) => { const t = testo(v).toLowerCase(); if (!t) return seVuoto; return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t); };
// Il consenso alle anteprime con persone vale SOLO se nella cella c'è esattamente «si» (o «sì»): niente x, ok, 1, true.
const consensoFirmato = (v) => ['si', 'sì'].includes(testo(v).toLowerCase());
const lette = (nodo) => $(nodo).all().map((i) => i.json || {}).filter((r) => has(r, 'row_number')); // solo righe vere del foglio
const partiRoma = (ms) => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
